<template><div class="space-y-7"><AppPageHeader eyebrow="Certificação" title="Certificados confiáveis" description="Gerencie validade, revogação e reemissão sem apagar o histórico de nenhuma versão."/><div v-if="error" class="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }}</div><section class="premium-card overflow-hidden"><div class="flex items-center justify-between border-b border-slate-100 px-5 py-4 sm:px-6"><div><p class="premium-kicker">Registro imutável</p><h2 class="mt-1 font-bold text-slate-900">Certificados emitidos</h2></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-500">{{ certificates.length }}</span></div><div v-if="loading" class="p-8 text-sm text-slate-400">Carregando…</div><div v-else-if="!certificates.length" class="m-5 rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center text-sm text-slate-400">Nenhum certificado emitido.</div><div v-else class="divide-y divide-slate-100"><article v-for="cert in certificates" :key="cert.id" class="p-5 sm:p-6"><div class="flex flex-col gap-5 lg:flex-row lg:items-center"><div class="flex min-w-0 flex-1 items-start gap-4"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-emerald-50 text-emerald-700"><NavIcon name="shield"/></span><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><p class="font-bold text-slate-900">{{ cert.certificate_number }}</p><span class="rounded-full border px-2.5 py-1 text-[10px] font-bold" :class="badge(cert)">{{ effective(cert) }}</span><span class="text-xs font-semibold text-slate-400">v{{ cert.version }}</span></div><p class="mt-2 text-xs leading-5 text-slate-400">Código <span class="font-mono text-slate-600">{{ cert.validation_code }}</span><br class="sm:hidden"> · emissão {{ date(cert.issued_at) }} · validade {{ date(cert.expires_at) }}</p><p v-if="cert.revocation_reason" class="mt-2 text-xs font-medium text-red-700">Motivo: {{ cert.revocation_reason }}</p></div></div><div class="w-full lg:w-[360px]"><input v-model="notes[cert.id]" placeholder="Informe o motivo da operação" class="w-full text-sm"/><div class="mt-2 flex justify-end gap-2"><button v-if="effective(cert)==='ACTIVE'" :disabled="!validNote(cert.id)" @click="revoke(cert)" class="rounded-xl border border-red-200 bg-white px-3.5 py-2 text-xs font-bold text-red-700 disabled:opacity-40">Revogar</button><button v-if="['REVOKED','EXPIRED','ACTIVE'].includes(effective(cert))" :disabled="!validNote(cert.id)" @click="reissue(cert)" class="rounded-xl px-3.5 py-2 text-xs font-bold text-white disabled:opacity-40" :style="{background:'var(--brand-primary)'}">Reemitir versão</button></div></div></div></article></div></section></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{listCertificatesAdmin,reissueCertificate,revokeCertificate}from'../api/certificateOps';import AppPageHeader from'../components/AppPageHeader.vue';import NavIcon from'../components/NavIcon.vue';const certificates=ref([]),loading=ref(true),error=ref(''),notes=reactive({});const date=v=>v?new Date(v).toLocaleDateString('pt-BR'):'Sem vencimento';const validNote=id=>(notes[id]||'').trim().length>=3;function effective(c){if(c.status==='REVOKED'||c.status==='SUPERSEDED')return c.status;if(c.expires_at&&new Date(c.expires_at)<=new Date())return'EXPIRED';return'ACTIVE'}function badge(c){const s=effective(c);return s==='ACTIVE'?'border-emerald-200 bg-emerald-50 text-emerald-700':s==='EXPIRED'?'border-amber-200 bg-amber-50 text-amber-700':s==='SUPERSEDED'?'border-slate-200 bg-slate-50 text-slate-600':'border-red-200 bg-red-50 text-red-700'}async function load(){loading.value=true;try{certificates.value=(await listCertificatesAdmin()).data}catch(e){error.value=e.response?.data?.detail||'Erro ao carregar certificados.'}finally{loading.value=false}}async function revoke(c){try{Object.assign(c,(await revokeCertificate(c.id,notes[c.id])).data);notes[c.id]=''}catch(e){error.value=e.response?.data?.detail||'Não foi possível revogar.'}}async function reissue(c){try{await reissueCertificate(c.id,notes[c.id]);notes[c.id]='';await load()}catch(e){error.value=e.response?.data?.detail||'Não foi possível reemitir.'}}onMounted(load)</script>
